import os
import torch


class Config:
    """
    Configuration for Idea 9: Context-Enhanced Hybrid Router-Generator.
    """

    # ==========================================
    # 1. Paths & Directories
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_9"

    # Subdirectories
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    SUBMISSION_DIR = os.path.join(WORKING_DIR, "submission")

    # Metadata Files (Generated by previous steps)
    TRAIN_FILE = os.path.join(METADATA_DIR, "train.csv")
    VAL_FILE = os.path.join(METADATA_DIR, "val.csv")
    TEST_FILE = os.path.join(METADATA_DIR, "test.csv")

    # Output Files
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure directories exist
    for d in [WORKING_DIR, CHECKPOINT_DIR, CACHE_DIR, SUBMISSION_DIR]:
        os.makedirs(d, exist_ok=True)

    # ==========================================
    # 2. Model Architectures
    # ==========================================
    # Router: Sequence Labeling (Token Classification)
    # DeBERTa-v3 is chosen for its disentangled attention, excellent for context dependency.
    ROUTER_MODEL_NAME = "microsoft/deberta-v3-base"
    ROUTER_MAX_LEN = 128  # Sufficient for sentence-level context

    # Generator: Sequence-to-Sequence
    # ByT5 is chosen for robustness to character-level variations and no OOV issues.
    GENERATOR_MODEL_NAME = "google/byt5-small"
    GENERATOR_MAX_INPUT_LEN = 384  # Bytes (approx 100-150 chars context)
    GENERATOR_MAX_TARGET_LEN = 256  # Bytes

    # ==========================================
    # 3. Training Hyperparameters
    # ==========================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # Router Training
    ROUTER_BATCH_SIZE = 32
    ROUTER_LR = 2e-5
    ROUTER_EPOCHS = 3
    ROUTER_WEIGHT_DECAY = 0.01
    ROUTER_PATIENCE = 2  # Early stopping patience

    # Generator Training
    GENERATOR_BATCH_SIZE = 16
    GENERATOR_LR = 3e-4
    GENERATOR_EPOCHS = 5
    GENERATOR_WEIGHT_DECAY = 0.01
    GENERATOR_PATIENCE = 2

    # ==========================================
    # 4. Class Taxonomy & Logic
    # ==========================================
    # Comprehensive list of classes observed in the dataset
    ALL_CLASSES = [
        "PLAIN",
        "PUNCT",
        "DATE",
        "LETTERS",
        "CARDINAL",
        "VERBATIM",
        "MEASURE",
        "ORDINAL",
        "DECIMAL",
        "MONEY",
        "ELECTRONIC",
        "TELEPHONE",
        "TIME",
        "ADDRESS",
        "DIGIT",
        "FRACTION",
    ]

    # Path A: Deterministic / Rule-based
    # These classes have strict formatting rules and low ambiguity if correctly classified.
    # Note: 'DIGIT' and 'DECIMAL' are included here as they are usually algorithmic.
    PATH_A_CLASSES = {
        "PLAIN",
        "PUNCT",
        "CARDINAL",
        "ORDINAL",
        "DIGIT",
        "LETTERS",
        "DECIMAL",
    }

    # Path B: Neural / Context-Aware Generator
    # These classes often require semantic understanding or complex expansion.
    PATH_B_CLASSES = {
        "DATE",
        "TIME",
        "MEASURE",
        "ADDRESS",
        "TELEPHONE",
        "ELECTRONIC",
        "VERBATIM",
        "MONEY",
        "FRACTION",
    }

    # Mappings for the Router
    LABEL2ID = {label: i for i, label in enumerate(ALL_CLASSES)}
    ID2LABEL = {i: label for label, i in LABEL2ID.items()}
    NUM_LABELS = len(ALL_CLASSES)

    # ==========================================
    # 5. Data Processing Constants
    # ==========================================
    # Context Window for Generator
    # We include +/- N tokens around the target for context
    CONTEXT_WINDOW_SIZE = 3

    # Special tokens for marking the target span in the generator input
    # ByT5 uses <extra_id_X> sentinels. We use 0 and 1 to bracket the target.
    # Format: "prefix <extra_id_0> target <extra_id_1> suffix"
    TARGET_START_TOKEN = "<extra_id_0>"
    TARGET_END_TOKEN = "<extra_id_1>"
